class ManagerSerializeTest : public BiosConfigTest
{
  protected:
    void SetUp() override
    {
        BiosConfigTest::SetUp();
        if (objServer && systemBus)
        {
            const char* testName =
                ::testing::UnitTest::GetInstance()->current_test_info()->name();
            std::string safeName;
            for (const char* p = testName; *p; ++p)
            {
                safeName += (*p == '/' || *p == '\\') ? '_' : *p;
            }
            persistPath = persistPath / safeName;
            std::filesystem::create_directories(persistPath);

            loadPath = persistPath / "load_target";
            std::filesystem::create_directories(loadPath);

            manager = std::make_unique<Manager>(*objServer, systemBus,
                                                persistPath.string());
            serializePath = persistPath / "test_serialize";
        }
    }

    void TearDown() override
    {
        drainIoContext();

        if (std::filesystem::exists(serializePath))
        {
            std::filesystem::remove(serializePath);
        }
        BiosConfigTest::TearDown();
    }

    static std::filesystem::path asyncSerializeTempPath(
        std::filesystem::path path)
    {
        path += ".tmp";
        return path;
    }

    bool hasAsyncSerializeTempFiles() const
    {
        if (!std::filesystem::exists(tempDir))
        {
            return false;
        }

        for (const auto& entry :
             std::filesystem::recursive_directory_iterator(tempDir))
        {
            if (entry.path().string().ends_with(".tmp"))
            {
                return true;
            }
        }

        return false;
    }

    void drainIoContext()
    {
        constexpr auto step = std::chrono::milliseconds(50);
        constexpr auto timeout = std::chrono::seconds(5);
        for (auto waited = std::chrono::milliseconds(0); waited < timeout;
             waited += step)
        {
            ioContext.restart();
            const auto handlers = ioContext.run_for(step);
            if (handlers == 0 && !hasAsyncSerializeTempFiles())
            {
                break;
            }
        }
    }

    bool drainUntilFileHasContent(const std::filesystem::path& path)
    {
        constexpr auto step = std::chrono::milliseconds(50);
        constexpr auto timeout = std::chrono::seconds(5);
        for (auto waited = std::chrono::milliseconds(0); waited < timeout;
             waited += step)
        {
            ioContext.restart();
            const auto handlers = ioContext.run_for(step);
            if (handlers == 0 && std::filesystem::exists(path) &&
                std::filesystem::file_size(path) > 0u)
            {
                return true;
            }
        }
        return false;
    }

    std::unique_ptr<Manager> manager;
    std::filesystem::path serializePath;
    std::filesystem::path loadPath;
};

